const cListaGruposOracao="676dcaa4ecceca5af8c527f1";var obj_go={};async function carregarDadosTrello(){await fetch("https://trello.com/b/nwnUfYoi/rcc-diocese-de-ji-parana.json",{}).then((e=>{if(!e.ok)throw new Error("Erro na requisição: "+e.status);return e.json()})).then((e=>{carregarTela(e)})).catch((e=>{console.error("Ocorreu um erro:",e)}))}function carregarCards(e){if(document.getElementsByClassName("card-item").length>=0){document.querySelectorAll(".card-item").forEach((e=>e.remove()))}let a=0;for(let o=0;o<e.length;o++)if(e[o].idList==cListaGruposOracao){let r=document.createElement("div");r.classList.add("card"),r.classList.add("container-go-item"),r.classList.add("card-item");let n=e[o].desc;n=n.replace("```json",""),n=n.replace("```","");let t=JSON.parse(n);r.innerHTML='<div class="card-body">\n        <div class="row">\n            <div class="col-sm-auto col-md-auto col-lg-auto col-xl-auto flex-fill">\n                <h3 class="nome-grupo"></h3>\n                <hr />\n                <h4 class="datahora-grupo"> </h4>\n                <h5 class="cidade-grupo"> <br /></h5>\n                <h5 class="local-grupo">Local: Comunidade Santo Agostinho<br /></h5>\n                <hr />\n                <p class="endereco-grupo">Endereço:Rua Acre, Jardim Novo Horizonte, Ouro Preto Do Oeste<br /></p>\n            </div>\n        </div>\n    </div>';let c=document.getElementById("filtroCidade").value,d=document.getElementById("filtroDiaSemana").value;t.cidadeGrupo!=c&&"<Selecione a cidade>"!=c||d!=t.diaSemanaGrupo&&"<selecione o dia da semana>"!=d||(r.getElementsByClassName("nome-grupo")[0].innerText=e[o].name,r.getElementsByClassName("cidade-grupo")[0].innerText=t.cidadeGrupo,r.getElementsByClassName("datahora-grupo")[0].innerText=t.diaSemanaGrupo+" às "+t.horarioGrupo,r.getElementsByClassName("local-grupo")[0].innerText=t.localGrupo,r.getElementsByClassName("endereco-grupo")[0].innerText=t.enderecoGrupo,r.getElementsByClassName("insta-grupo").length>0&&(r.getElementsByClassName("insta-grupo")[0].src=t.urlPostIntaGrupo),document.getElementsByClassName("container-go")[0].appendChild(r),a++)}0==a?(document.getElementById("carregando-go").style.display="block",document.getElementById("carregando-go").innerText="Grupo de oração não encontrado!"):document.getElementById("carregando-go").style.display="none"}function carregarTela(e){""!=(obj_go=e).id?(document.getElementById("carregando-go").style.display="none",document.getElementById("carregando-go").innerText="True",carregarCards(obj_go.cards)):document.getElementById("carregando-go").innerText="Grupo de oração não encontrado!"}carregarDadosTrello(),document.getElementById("btnFiltrar").onclick=function(){carregarCards(obj_go.cards)};